import{_ as a,o,c as e,a5 as r}from"./chunks/framework.BjM_ivYE.js";const u=JSON.parse('{"title":"도킹 반복 재시도","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/troubleshooting/docking-retry.md","filePath":"ko/manual/troubleshooting/docking-retry.md","lastUpdated":1789720001000}'),s={name:"ko/manual/troubleshooting/docking-retry.md"};function l(i,t,n,d,c,h){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="도킹-반복-재시도" tabindex="-1">도킹 반복 재시도 <a class="header-anchor" href="#도킹-반복-재시도" aria-label="Permalink to &quot;도킹 반복 재시도&quot;">​</a></h1><p>도킹 스테이션에 도킹하지 못하고 로봇이 계속 다시 시도하는 경우입니다. 대부분 <strong>마커가 보이지 않는 것</strong>이 원인이며, 그다음이 <strong>정렬 오차</strong>입니다.</p><h2 id="first-checks" tabindex="-1">먼저 확인할 것 <a class="header-anchor" href="#first-checks" aria-label="Permalink to &quot;먼저 확인할 것 {#first-checks}&quot;">​</a></h2><ul><li>로봇과 도킹 스테이션의 거리가 <strong>3 m 이내</strong>인지 확인합니다.</li><li>로봇의 <strong>전방 또는 후방 카메라가 도킹 스테이션을 향하고</strong> 있는지 확인합니다.</li><li>도킹 스테이션의 마커에 가림막 · 이물질 · 물기가 없는지 확인합니다.</li><li>도킹 스테이션에 전원이 들어와 있는지 확인합니다.</li></ul><h2 id="marker-not-found" tabindex="-1">마커를 인식하지 못합니다 <a class="header-anchor" href="#marker-not-found" aria-label="Permalink to &quot;마커를 인식하지 못합니다 {#marker-not-found}&quot;">​</a></h2><p><strong>원인:</strong> 도킹은 도킹 스테이션에 붙은 마커를 보고 위치를 계산합니다. 아래 조건 중 하나라도 맞지 않으면 인식되지 않습니다.</p><ul><li>거리가 <strong>3 m를 넘습니다.</strong></li><li>마커의 일부만 보입니다. 마커는 여러 개가 한 판에 배치되어 있고, <strong>그중 일부 이상이 온전히 보여야</strong> 위치를 계산할 수 있습니다.</li><li>마커가 그늘 · 역광 · 반사로 잘 보이지 않습니다.</li></ul><p><strong>해결:</strong></p><ol><li>로봇을 도킹 스테이션 <strong>정면 3 m 이내</strong>로 옮깁니다.</li><li>마커 표면을 닦고, 가리는 물건을 치웁니다.</li><li>직사광선이나 강한 반사가 있으면 조명 조건을 바꾸거나 스테이션 위치를 옮깁니다.</li><li>다시 도킹을 시작합니다.</li></ol><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">참고</p><p>도킹 중에는 로봇을 손으로 움직이지 마세요. 도킹 스테이션도 바닥에 고정되어 있어야 합니다.</p></div></div><h2 id="alignment-off" tabindex="-1">마커는 인식하는데 자세가 어긋납니다 <a class="header-anchor" href="#alignment-off" aria-label="Permalink to &quot;마커는 인식하는데 자세가 어긋납니다 {#alignment-off}&quot;">​</a></h2><p><strong>원인:</strong> 로봇이 도킹 스테이션 앞까지는 오는데 좌우 또는 앞뒤 위치가 미세하게 맞지 않는 경우입니다. 정렬 오프셋 값을 조정해야 합니다.</p><p><strong>해결:</strong> 아래 <a href="#dock-parameters">도킹 파라미터 조정</a> 절차에 따라 <code>Offset X</code> · <code>Offset Y</code> 값을 조정합니다.</p><h2 id="dock-parameters" tabindex="-1">도킹 파라미터 조정 <a class="header-anchor" href="#dock-parameters" aria-label="Permalink to &quot;도킹 파라미터 조정 {#dock-parameters}&quot;">​</a></h2><p>도킹 정렬 오프셋과 재시도 횟수는 앱의 <strong>로봇 설정 → 캘리브레이션 → 도킹 캘리브레이션</strong>에서 확인하고 바꿀 수 있습니다.</p><h3 id="preparation" tabindex="-1">사전 준비 <a class="header-anchor" href="#preparation" aria-label="Permalink to &quot;사전 준비 {#preparation}&quot;">​</a></h3><ul><li>도킹을 시험할 수 있는 위치로 로봇을 이동해 주세요.</li><li>주변에 장애물이 없도록 해 주세요.</li><li>앱이 로봇에 연결된 상태여야 합니다.</li></ul><h3 id="procedure" tabindex="-1">진행 순서 <a class="header-anchor" href="#procedure" aria-label="Permalink to &quot;진행 순서 {#procedure}&quot;">​</a></h3><ol><li>앱에서 <strong>로봇 설정 → 캘리브레이션</strong>을 열고 아래로 내려 <strong>도킹 캘리브레이션</strong> 절로 갑니다. 화면에 들어가면 현재 값이 자동으로 읽힙니다 — 다시 읽으려면 <code>다시 읽기</code>를 누릅니다.</li><li>오차가 있는 항목의 값을 고칩니다.</li><li><code>적용</code>을 눌러 로봇에 저장합니다. 저장되면 로봇이 실제로 반영한 값으로 화면이 갱신되고 <em>적용됨 (로봇 값으로 재확인)</em> 이 표시됩니다.</li><li>위 <strong>2~3번</strong>을 반복해 도킹이 안정될 때까지 조정합니다.</li><li>조정이 끝나면 평소처럼 도킹 기능을 사용하면 됩니다.</li></ol><p>값을 되돌리려면 <code>기본값</code>을 누릅니다 — 칸에 출고 기본값이 채워질 뿐이므로 <strong><code>적용</code>을 눌러야 로봇에 저장됩니다.</strong></p><h3 id="parameters" tabindex="-1">수정 가능한 파라미터 <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;수정 가능한 파라미터 {#parameters}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>항목</th><th>의미</th><th>기본값</th></tr></thead><tbody><tr><td><code>Offset X (m)</code></td><td>로봇 기준 X 방향 위치 보정값</td><td>—</td></tr><tr><td><code>Offset Y (m)</code></td><td>로봇 기준 Y 방향 위치 보정값</td><td>—</td></tr><tr><td><code>Req Count</code></td><td>마커(충전기) 포즈 요청 시 유효한 응답이 없을 때 허용하는 누적 실패 횟수 상한</td><td>300</td></tr><tr><td><code>Try Count</code></td><td>도킹 실패 후 다시 시도하는 횟수</td><td>10</td></tr></tbody></table><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>재시도 횟수를 늘리는 것은 근본 해결이 아닙니다. 마커가 보이지 않는 상태에서 횟수만 늘리면 실패를 더 오래 반복할 뿐입니다. 위의 인식 조건부터 확인하세요.</p></div></div><h2 id="still-stuck" tabindex="-1">그래도 해결되지 않으면 <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;그래도 해결되지 않으면 {#still-stuck}&quot;">​</a></h2><p><strong><a href="/RBQ/ko/manual/gui/logs.html#real-time">로그 → Real Time</a></strong> 를 열고 도킹을 시작한 뒤 올라오는 메시지를 확인하세요. <code>Marker Not Found</code>, <code>too far</code> 등의 문구가 함께 있으면 알려주시면 확인이 빠릅니다.</p><p>도킹 스테이션 설치 조건은 <a href="/RBQ/ko/manual/operation/charging.html">충전하기</a>를 참고하세요.</p><p><strong>→ <a href="/RBQ/ko/manual/support/">기술지원 요청</a></strong></p>',27)])])}const g=a(s,[["render",l]]);export{u as __pageData,g as default};
